use std::cell::{Cell, RefCell};
std::thread_local! {
    static NO_DROP: Cell<bool> = const { Cell::new(false) };
    static DROPPABLE: RefCell<Vec<u8>> = const { RefCell::new(Vec::new()) };
}
pub fn touch() {
    NO_DROP.with(|value| value.set(true));
    DROPPABLE.with(|value| value.borrow_mut().push(1));
}
